package com.yeyamo_mobile.api.moderation_trust_service.infrastructure.messaging;import static org.mockito.Mockito.*;import java.util.UUID;import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.moderation_trust_service.application.ModerationService;
class SourceEventConsumerTests{@Test void replayIsIgnoredAfterPersistentReceipt()throws Exception{UUID id=UUID.randomUUID();ModerationService service=mock(ModerationService.class);ProcessedEventRepository receipts=mock(ProcessedEventRepository.class);when(receipts.existsById(id)).thenReturn(false,true);SourceEventConsumer c=new SourceEventConsumer(new ObjectMapper(),service,receipts);String raw=("{\"eventId\":\"%s\",\"eventType\":\"content.post.deleted\",\"eventVersion\":1,\"producer\":\"content-service\",\"aggregateId\":\"p1\",\"actorId\":\"u1\",\"correlationId\":\"c1\"}").formatted(id);c.consume(raw,"content-service");c.consume(raw,"content-service");verify(service,times(1)).recordExternal(id.toString(),"content.post.deleted","p1","u1","c1","content-service");verify(receipts,times(1)).save(any());}}
